const completeOutbound = node({
  type: 'n8n-nodes-base.code', version: 2,
  config: { name: 'Complete Outbound Contact', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// FINMENTOR Lead Intelligence v1 — confirm the Telegram Client Transport result.\n// Only a confirmed `{ ok: true }` delivery is logged as a successful outbound contact.\n\nconst LI = (function () {\nconst INFORMATION_KIND = Object.freeze({\n  CLIENT_FACT: 'CLIENT_FACT',\n  FINMENTOR_INTERPRETATION: 'FINMENTOR_INTERPRETATION',\n  NEEDS_VERIFICATION: 'NEEDS_VERIFICATION',\n  OWNER_CONFIRMED_FACT: 'OWNER_CONFIRMED_FACT',\n  OWNER_NOTE: 'OWNER_NOTE'\n});\n\nconst CONTACT_LABEL = Object.freeze({ telegram: 'Telegram', phone: 'Телефон', email: 'Email' });\nconst OUTCOME_CODES = Object.freeze([\n  'PROBLEM_CONFIRMED', 'HYPOTHESIS_CHANGED', 'MORE_DATA_NEEDED', 'NO_TASK_NOW', 'READY_TO_DISCUSS'\n]);\nconst PRODUCT_CODES = Object.freeze([\n  'CFO_ADVISORY_SESSION', 'FINANCIAL_HEALTH_CHECK', 'BUSINESS_CONTROL_SYSTEM',\n  'CFO_CONTROL_PARTNER', 'CFO_AI_CONTROL', 'NEEDS_CLARIFICATION'\n]);\n\nfunction text(value, max) {\n  return String(value === undefined || value === null ? '' : value)\n    .replace(/\\s+/g, ' ').trim().slice(0, max || 1200);\n}\n\nfunction lines(value, max, each) {\n  const source = Array.isArray(value) ? value : String(value || '').split(/\\r?\\n/);\n  return source.map((v) => text(v, each || 500)).filter(Boolean).slice(0, max || 10);\n}\n\nfunction channelKey(value) {\n  const v = text(value, 60).toLowerCase();\n  if (/telegram|телеграм|^tg$/.test(v)) return 'telegram';\n  if (/e-?mail|почт/.test(v)) return 'email';\n  if (/phone|телефон|звон/.test(v)) return 'phone';\n  return '';\n}\n\nfunction validEmail(value) {\n  const v = text(value, 180).toLowerCase();\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(v) ? v : '';\n}\n\nfunction validPhone(value) {\n  const raw = text(value, 80);\n  if (!raw || raw.includes('@') || /telegram|t\\.me/i.test(raw)) return '';\n  const core = raw.split(/[(,;]/)[0].trim();\n  if (!/^[+\\d][\\d\\s().\\-/]*$/.test(core)) return '';\n  const digits = core.replace(/\\D/g, '');\n  return digits.length >= 6 && digits.length <= 15 ? raw : '';\n}\n\nfunction telegramUsername(value) {\n  let v = text(value, 80).replace(/^https?:\\/\\/t\\.me\\//i, '').replace(/^@/, '');\n  return /^[A-Za-z][A-Za-z0-9_]{2,31}$/.test(v) ? '@' + v : '';\n}\n\nfunction telegramNumeric(value) {\n  const v = text(value, 30);\n  return /^-?\\d{5,20}$/.test(v) ? v : '';\n}\n\n// Preference is a statement by the client. Reachability is evidence held by FINMENTOR. They are\n// intentionally calculated on different paths and never collapsed into a single `contact` value.\nfunction buildReachability(input) {\n  const i = input || {};\n  const preferred = channelKey(i.preferred_contact_channel || i.contact_channel);\n  const phone = validPhone(i.phone);\n  const email = validEmail(i.email);\n  const username = telegramUsername(i.telegram_username || i.telegram);\n  const numeric = telegramNumeric(i.telegram_chat_id || i.telegram_user_id || i.telegram);\n  const trustedTelegramFlow = i.telegram_route_verified === true\n    || /telegram_premium|telegram_miniapp|concierge|miniapp/i.test(text(i.source_channel, 80));\n  const verifiedNumeric = trustedTelegramFlow ? numeric : '';\n  const telegram = username || verifiedNumeric;\n\n  const reachable = [];\n  if (telegram) reachable.push({ key: 'telegram', label: CONTACT_LABEL.telegram, value: telegram, verified: true });\n  if (phone) reachable.push({ key: 'phone', label: CONTACT_LABEL.phone, value: phone, verified: false });\n  if (email) reachable.push({ key: 'email', label: CONTACT_LABEL.email, value: email, verified: false });\n\n  return {\n    preferred_contact_channel: preferred,\n    preferred_label: CONTACT_LABEL[preferred] || 'Не указано',\n    reachable_channels: reachable,\n    telegram: {\n      reachable: !!telegram,\n      verified: !!telegram,\n      route: telegram,\n      reason: telegram ? '' : (preferred === 'telegram' ? 'Telegram-контакт не подключён' : '')\n    },\n    phone,\n    email\n  };\n}\n\nfunction fact(id, label, value, sourcePath) {\n  const v = text(value, 1000);\n  if (!v) return null;\n  return {\n    id: text(id, 60), label: text(label, 120), value: v,\n    source_path: text(sourcePath, 200), kind: INFORMATION_KIND.CLIENT_FACT\n  };\n}\n\n// Customer publication is a promise made by an originating journey, not an inference from its\n// channel. Only a small explicit allow-list can grant eligibility. Everything else (including\n// Niagara's «Пока только самооценка») is owner-only and fails closed.\nfunction explicitClientResultRequest(value) {\n  if (value === true || value === 1) return true;\n  const v = text(value, 180).toLowerCase().replace(/ё/g, 'е');\n  return [\n    'true', 'yes', 'да', '1',\n    'да, нужен разбор', 'хочу получить разбор', 'получить разбор', 'да, хочу получить разбор',\n    'vreau analiza', 'doresc analiza', 'da, vreau analiza'\n  ].includes(v);\n}\n\nfunction clientResultEligibility(input) {\n  const i = input || {};\n  const source = text(i.source_channel, 80).toLowerCase();\n  const sourcePath = text(i.source_path, 220);\n  if (!/^(website_xray|telegram_premium|telegram_miniapp)$/.test(source)) {\n    return { eligible: false, reason: 'JOURNEY_NOT_SUPPORTED', source_path: sourcePath };\n  }\n  if (!explicitClientResultRequest(i.explicit_request)) {\n    return {\n      eligible: false,\n      reason: presentValue(i.explicit_request) ? 'EXPLICITLY_NOT_REQUESTED' : 'NO_EXPLICIT_PROMISE',\n      source_path: sourcePath\n    };\n  }\n  return { eligible: true, reason: 'EXPLICITLY_REQUESTED', source_path: sourcePath };\n}\n\nfunction presentValue(value) {\n  return value !== undefined && value !== null && text(value, 180) !== '';\n}\n\n// Input values must already have been selected from Leads / Raw JSON / Pipeline. The function does\n// no inference: labels are presentation, values are passed through from the source snapshot.\nfunction buildClientFacts(source) {\n  const s = source || {};\n  const out = [\n    fact('main_problem', 'Основная проблема', s.main_problem, s.main_problem_source || 'Pipeline.main_pain'),\n    fact('existing_setup', 'Что уже есть', lines(s.existing_setup, 8, 160).join('; '), s.existing_setup_source || 'Leads.Raw JSON'),\n    fact('desired_result', 'Какой результат хочет получить', s.desired_result, s.desired_result_source || 'Pipeline.selected_goals'),\n    fact('desired_first_step', 'Первый шаг, выбранный клиентом', s.desired_first_step, s.desired_first_step_source || 'Leads.Raw JSON.intake.business_pain.desired_first_step'),\n    fact('urgency', 'Срочность', s.urgency, s.urgency_source || 'Leads.Raw JSON'),\n    fact('financial_system', 'Что сообщил о финансовой системе', s.financial_system, s.financial_system_source || 'Leads.Raw JSON'),\n    fact('documents', 'Какие материалы доступны', s.documents, s.documents_source || 'Pipeline.selected_documents'),\n    fact('capital_context', 'Капитал и финансирование', s.capital_context, s.capital_context_source || 'Leads.Raw JSON')\n  ].filter(Boolean);\n  return out;\n}\n\nfunction evidenceIds(value, known) {\n  return lines(value, 8, 60).filter((id) => known.has(id));\n}\n\nfunction interpretation(item, known) {\n  const i = item && typeof item === 'object' ? item : {};\n  const conclusion = text(i.conclusion || i.observation, 700);\n  if (!conclusion) return null;\n  return {\n    kind: INFORMATION_KIND.FINMENTOR_INTERPRETATION,\n    conclusion,\n    evidence_fact_ids: evidenceIds(i.evidence_fact_ids || i.evidence, known),\n    hypothesis: text(i.hypothesis, 700),\n    economic_implication: text(i.economic_implication, 500)\n  };\n}\n\nfunction normalizeOwnerBrief(raw, context) {\n  const r = raw && typeof raw === 'object' ? raw : {};\n  const c = context || {};\n  const facts = Array.isArray(c.client_facts)\n    ? c.client_facts.filter((x) => x && x.kind === INFORMATION_KIND.CLIENT_FACT && text(x.value))\n    : [];\n  const known = new Set(facts.map((x) => x.id));\n  const diagnoses = (Array.isArray(r.diagnoses) ? r.diagnoses : [])\n    .map((x) => interpretation(x, known)).filter(Boolean).slice(0, 4);\n  const painMap = (Array.isArray(r.pain_map) ? r.pain_map : []).map((p) => {\n    const x = p && typeof p === 'object' ? p : {};\n    if (!text(x.area)) return null;\n    return {\n      kind: INFORMATION_KIND.FINMENTOR_INTERPRETATION,\n      area: text(x.area, 120), attention: text(x.attention || 'Требует внимания', 80),\n      observation: text(x.observation, 500), consequence: text(x.consequence, 500),\n      economic_category: text(x.economic_category, 80),\n      evidence_fact_ids: evidenceIds(x.evidence_fact_ids || x.evidence, known)\n    };\n  }).filter(Boolean).slice(0, 4);\n  const unknowns = (Array.isArray(r.unknowns) ? r.unknowns : []).map((u) => {\n    const x = u && typeof u === 'object' ? u : { item: u };\n    const item = text(x.item || x.missing_information, 400);\n    return item ? { kind: INFORMATION_KIND.NEEDS_VERIFICATION, item, why: text(x.why || x.why_it_matters, 500) } : null;\n  }).filter(Boolean).slice(0, 7);\n  const questions = (Array.isArray(r.discovery_questions) ? r.discovery_questions : []).map((q) => {\n    const x = q && typeof q === 'object' ? q : {};\n    const question = text(x.question, 500); const why = text(x.why || x.purpose, 500);\n    return question && why ? { question, why, kind: INFORMATION_KIND.FINMENTOR_INTERPRETATION } : null;\n  }).filter(Boolean).slice(0, 7);\n  const sh = r.solution_hypothesis && typeof r.solution_hypothesis === 'object' ? r.solution_hypothesis : {};\n  const product = PRODUCT_CODES.includes(String(sh.product || '').toUpperCase())\n    ? String(sh.product).toUpperCase() : 'NEEDS_CLARIFICATION';\n  const nh = r.next_action && typeof r.next_action === 'object' ? r.next_action : {};\n\n  return {\n    schema_version: 'lead-intelligence-v1',\n    generated_at: text(c.generated_at || new Date().toISOString(), 40),\n    intelligence_version: Number(c.intelligence_version) > 0 ? Number(c.intelligence_version) : 1,\n    header: {\n      company: text(c.company, 160), contact_name: text(c.contact_name, 120), role: text(c.role, 100),\n      business: text(c.business, 160), scale: text(c.scale, 160), source: text(c.source, 80),\n      lead_status: text(c.lead_status, 100), data_quality: text(c.data_quality || 'Требует проверки', 120),\n      commercial_intent: c.commercial_intent_confirmed === true ? text(c.commercial_intent, 160) : 'Не подтверждён',\n      next_action: text(c.next_action || nh.action, 300), next_action_date: text(c.next_action_date || nh.due_date, 40),\n      diagnostic_score: c.diagnostic_score === '' || c.diagnostic_score === null || c.diagnostic_score === undefined ? null : Number(c.diagnostic_score),\n      financial_zone: text(c.financial_zone || 'UNKNOWN', 20)\n    },\n    contact: c.contact || buildReachability(c),\n    client_facts: facts,\n    diagnoses,\n    pain_map: painMap,\n    unknowns,\n    first_meeting_objective: text(r.first_meeting_objective, 700),\n    conversation_opening: text(r.conversation_opening, 900),\n    discovery_questions: questions,\n    solution_hypothesis: {\n      kind: INFORMATION_KIND.FINMENTOR_INTERPRETATION,\n      product,\n      format: text(sh.format || 'Сначала требуется уточнение', 220),\n      rationale: text(sh.rationale, 700),\n      confirmation_conditions: lines(sh.confirmation_conditions, 6, 400),\n      if_confirmed: text(sh.if_confirmed, 500),\n      do_not_offer_yet: text(sh.do_not_offer_yet, 500)\n    },\n    next_action: {\n      action: text(nh.action || c.next_action, 300), purpose: text(nh.purpose, 500),\n      success_condition: text(nh.success_condition, 700), due_date: text(nh.due_date || c.next_action_date, 40)\n    },\n    owner_confirmed_facts: Array.isArray(c.owner_confirmed_facts) ? c.owner_confirmed_facts.slice(0, 20) : [],\n    owner_notes: Array.isArray(c.owner_notes) ? c.owner_notes.slice(0, 20) : [],\n    history: Array.isArray(c.history) ? c.history.slice(0, 30) : [],\n    client_result_eligible: c.client_result_eligible === true,\n    client_result_eligibility_reason: text(c.client_result_eligibility_reason, 80)\n  };\n}\n\nfunction briefErrors(brief) {\n  const b = brief || {}; const errors = [];\n  if (!Array.isArray(b.client_facts) || !b.client_facts.length) errors.push('client_facts empty');\n  if (!Array.isArray(b.diagnoses) || b.diagnoses.length < 2 || b.diagnoses.length > 4) errors.push('diagnoses must contain 2..4 items');\n  if (!Array.isArray(b.pain_map) || b.pain_map.length < 1 || b.pain_map.length > 4) errors.push('pain_map must contain 1..4 items');\n  if (!Array.isArray(b.unknowns) || b.unknowns.length < 1 || b.unknowns.length > 7) errors.push('unknowns must contain 1..7 items');\n  if (!text(b.first_meeting_objective)) errors.push('first_meeting_objective empty');\n  if (!text(b.conversation_opening)) errors.push('conversation_opening empty');\n  if (!Array.isArray(b.discovery_questions) || b.discovery_questions.length < 5 || b.discovery_questions.length > 7) errors.push('discovery_questions must contain 5..7 items');\n  if ((b.discovery_questions || []).some((q) => !text(q.why))) errors.push('every discovery question needs a purpose');\n  if (!text(b.solution_hypothesis && b.solution_hypothesis.rationale)) errors.push('solution rationale empty');\n  if (!(b.solution_hypothesis && b.solution_hypothesis.confirmation_conditions || []).length) errors.push('solution confirmation conditions empty');\n  if (!text(b.next_action && b.next_action.action) || !text(b.next_action && b.next_action.purpose) || !text(b.next_action && b.next_action.success_condition)) errors.push('next_action incomplete');\n  for (const f of b.client_facts || []) if (f.kind !== INFORMATION_KIND.CLIENT_FACT || !f.source_path) errors.push('client fact provenance missing');\n  for (const d of b.diagnoses || []) if (d.kind !== INFORMATION_KIND.FINMENTOR_INTERPRETATION) errors.push('diagnosis provenance invalid');\n  for (const u of b.unknowns || []) if (u.kind !== INFORMATION_KIND.NEEDS_VERIFICATION) errors.push('unknown provenance invalid');\n  return [...new Set(errors)];\n}\n\nconst api = {\n  INFORMATION_KIND, OUTCOME_CODES, PRODUCT_CODES, CONTACT_LABEL,\n  text, lines, channelKey, validEmail, validPhone, telegramUsername, telegramNumeric,\n  explicitClientResultRequest, clientResultEligibility,\n  buildReachability, buildClientFacts, normalizeOwnerBrief, briefErrors\n};\nreturn api;\n})();\nconst LI_RENDER = (function () {\nfunction esc(value) {\n  return String(value === undefined || value === null ? '' : value)\n    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\n}\nfunction present(v) { return String(v === undefined || v === null ? '' : v).trim() !== ''; }\nfunction arr(v) { return Array.isArray(v) ? v : []; }\nfunction p(v, cls) { return present(v) ? '<p' + (cls ? ' class=\"' + cls + '\"' : '') + '>' + esc(v) + '</p>' : ''; }\nfunction list(v, fn, cls) { const x = arr(v); return x.length ? '<div class=\"' + (cls || 'list') + '\">' + x.map(fn).join('') + '</div>' : '<p class=\"empty\">Не указано</p>'; }\nfunction statusLabel(value) {\n  const labels = {\n    AI_DRAFT: 'Черновик FINMENTOR', OWNER_REVIEW: 'Проверка владельцем', OWNER_EDITED: 'Отредактировано',\n    CLIENT_READY: 'Доступно клиенту', CLIENT_NOTIFIED: 'Клиент уведомлён', CLIENT_VIEWED: 'Клиент открыл',\n    ANALYSIS_FAILED: 'Не сформировано'\n  };\n  return labels[String(value || '')] || 'В работе';\n}\nfunction sourceLabel(value) {\n  const s = String(value || '');\n  if (/website_xray|xray/i.test(s)) return 'Financial X-Ray';\n  if (/telegram_premium|miniapp/i.test(s)) return 'Mini App';\n  if (/both/i.test(s)) return 'Financial X-Ray + Mini App';\n  return s || 'Источник не определён';\n}\nfunction zoneLabel(value) {\n  return ({ GREEN: 'Устойчивая зона', YELLOW: 'Требует внимания', ORANGE: 'Существенные пробелы', RED: 'Критическая зона', UNKNOWN: 'Без оценки' })[String(value || '').toUpperCase()] || 'Без оценки';\n}\nfunction provenanceLabel(kind) {\n  return ({\n    CLIENT_FACT: 'КЛИЕНТ ГОВОРИТ', FINMENTOR_INTERPRETATION: 'FINMENTOR ВИДИТ',\n    NEEDS_VERIFICATION: 'НУЖНО ПРОВЕРИТЬ', OWNER_CONFIRMED_FACT: 'ПОДТВЕРЖДЕНО ВЛАДЕЛЬЦЕМ',\n    OWNER_NOTE: 'ЗАМЕТКА ВЛАДЕЛЬЦА'\n  })[kind] || '';\n}\nfunction field(name, value, label, opts) {\n  const o = opts || {}; const tag = o.multiline === false ? 'input' : 'textarea';\n  const control = tag === 'textarea'\n    ? '<textarea name=\"' + esc(name) + '\" rows=\"' + (o.rows || 4) + '\" maxlength=\"' + (o.max || 4000) + '\">' + esc(value) + '</textarea>'\n    : '<input name=\"' + esc(name) + '\" value=\"' + esc(value) + '\" maxlength=\"' + (o.max || 300) + '\">';\n  return '<label class=\"edit-field\"><span>' + esc(label) + '</span>' + control + (o.hint ? '<small>' + esc(o.hint) + '</small>' : '') + '</label>';\n}\nfunction authInputs(auth, action) {\n  const a = auth || {};\n  return '<input type=\"hidden\" name=\"a\" value=\"' + esc(a.analysis_id) + '\">'\n    + '<input type=\"hidden\" name=\"t\" value=\"' + esc(a.token) + '\">'\n    + '<input type=\"hidden\" name=\"action\" value=\"' + esc(action) + '\">';\n}\nfunction asText(items, fn) { return arr(items).map(fn || ((x) => x)).filter(present).join('\\n'); }\n\nconst SHELL_CSS = `\n:root{--navy:#091626;--navy2:#10233a;--ink:#142233;--muted:#66717e;--paper:#f7f3eb;--white:#fffdf8;--gold:#ae8a47;--gold2:#d6c49c;--line:#dcd5c7;--fact:#315d70;--verify:#8f5c27;--ok:#325e4d;--shadow:0 24px 70px rgba(8,20,36,.14)}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#e8e5df;color:var(--ink);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;line-height:1.58}button,input,textarea,select{font:inherit}a{color:inherit}.topbar{height:54px;background:var(--navy);color:#f5efe1;display:flex;align-items:center;justify-content:space-between;padding:0 30px;letter-spacing:.04em}.brand{font-family:Georgia,serif;font-weight:700;letter-spacing:.14em}.topstate{font-size:12px;color:var(--gold2);text-transform:uppercase}.paper{max-width:1160px;margin:26px auto 70px;background:var(--paper);box-shadow:var(--shadow);min-height:900px}.hero{background:var(--navy);color:#fff;padding:46px 58px 42px;border-top:3px solid var(--gold)}.eyebrow,.section-no,.kind,.micro,.edit-field>span,.path-step{font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.eyebrow{color:var(--gold2)}h1{font-family:Georgia,\"Times New Roman\",serif;font-size:46px;line-height:1.04;margin:13px 0 9px;font-weight:600}.identity{font-size:18px;color:#e1ded6;margin:0}.hero-layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(260px,.65fr);gap:42px;align-items:end}.hero-context{margin:13px 0 0;color:#b8c0c9;font-size:14px}.secondary-line{margin-top:18px;color:#9da9b7;font-size:12px;letter-spacing:.03em}.contact-card{border-top:1px solid rgba(214,196,156,.55);padding-top:17px}.contact-card .micro{color:var(--gold2)}.contact-card strong{display:block;font-family:Georgia,serif;font-size:20px;font-weight:500;margin:5px 0}.contact-card p{margin:4px 0;color:#dce1e5;font-size:13px}.warn{color:#e0b87a!important}.hero-priority{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:0;margin-top:34px;border:1px solid rgba(214,196,156,.3)}.hero-signal{padding:20px 22px;border-right:1px solid rgba(214,196,156,.25)}.hero-signal:last-child{border-right:0}.hero-signal .micro{color:#aeb7c2}.hero-signal strong{display:block;margin-top:7px;font-size:15px;line-height:1.45}.executive-path{max-width:980px;margin:0 auto;padding:40px 54px 10px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.path-card{background:var(--white);padding:20px 21px 22px;border-top:2px solid var(--gold);min-height:150px}.path-step{color:var(--gold)}.path-card h2{font-family:Georgia,serif;font-size:18px;line-height:1.2;margin:9px 0 8px;font-weight:600}.path-card p{font-size:13px;line-height:1.48;margin:0;color:#465363}.memo{max-width:850px;margin:0 auto;padding:38px 54px 70px}.section{display:grid;grid-template-columns:74px 1fr;gap:18px;padding:37px 0;border-top:1px solid var(--line)}.section:first-child{padding-top:12px}.section-no{color:var(--gold);padding-top:8px}.section h2{font-family:Georgia,serif;font-size:27px;line-height:1.2;margin:0 0 21px;font-weight:600}.kind{display:inline-block;margin-bottom:8px}.kind.fact{color:var(--fact)}.kind.interpretation{color:var(--gold)}.kind.verify{color:var(--verify)}.fact-row{padding:0 0 18px;margin:0 0 18px;border-bottom:1px solid #e5ded2}.fact-row:last-child{border:0;margin-bottom:0}.fact-row h3,.diagnosis h3,.pain h3{font-size:13px;margin:0 0 6px;color:#53606e}.fact-row p,.diagnosis p,.pain p{margin:0;font-size:16px}.diagnosis{padding:0 0 23px;margin:0 0 23px;border-bottom:1px solid #e5ded2}.diagnosis:last-child{border:0}.evidence{margin-top:9px!important;font-size:12px!important;color:var(--muted)}.hypothesis{margin-top:9px!important;color:#39495c}.pain-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.pain{background:var(--white);padding:22px;border-left:2px solid var(--gold)}.pain .attention{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--verify);margin-bottom:11px}.why{color:var(--muted);font-size:14px!important;margin-top:9px!important}.unknown{display:grid;grid-template-columns:24px 1fr;gap:12px;margin:0 0 18px}.unknown .mark{font-family:Georgia,serif;color:var(--verify);font-size:20px}.unknown strong{display:block;font-size:15px}.unknown p{margin:3px 0 0;color:var(--muted);font-size:14px}.statement{font-family:Georgia,serif;font-size:23px;line-height:1.45;border-left:3px solid var(--gold);padding:6px 0 6px 22px;margin:0}.opening{background:var(--navy2);color:#fbf7ed;padding:28px 30px;font-family:Georgia,serif;font-size:21px;line-height:1.5}.question{display:grid;grid-template-columns:33px 1fr;gap:14px;padding:0 0 21px;margin-bottom:21px;border-bottom:1px solid var(--line)}.question:last-child{border:0}.qno{font-family:Georgia,serif;color:var(--gold);font-size:19px}.question strong{display:block;font-size:16px}.question p{margin:7px 0 0;color:var(--muted);font-size:13px}.solution{background:#eee8dc;padding:27px 29px}.solution-row{margin:0 0 19px}.solution-row:last-child{margin:0}.solution-row .micro{color:#7c6a48}.solution-row p{margin:5px 0 0}.conditions{margin:6px 0 0;padding-left:19px}.decision{display:grid;grid-template-columns:1fr 1fr;gap:23px}.decision>div{padding-top:14px;border-top:2px solid var(--gold)}.decision p{margin:5px 0;color:var(--muted)}.owner-note{background:#e9ede8;border-left:3px solid var(--ok);padding:17px 20px;margin-bottom:12px}.owner-note p{margin:4px 0}.details{border-top:1px solid var(--line);padding:18px 0}.details summary{cursor:pointer;font-weight:700;list-style:none;display:flex;justify-content:space-between}.details summary:after{content:\"+\";color:var(--gold);font-size:20px}.details[open] summary:after{content:\"−\"}.details-body{padding:17px 0;color:var(--muted)}.actionsbar{position:sticky;bottom:0;background:rgba(247,243,235,.97);backdrop-filter:blur(10px);border-top:1px solid var(--line);display:flex;gap:10px;justify-content:flex-end;padding:14px 26px;z-index:8}.btn{display:inline-block;border:1px solid var(--navy);background:transparent;color:var(--navy);padding:10px 17px;text-decoration:none;font-weight:700;cursor:pointer;text-align:center}.btn.primary{background:var(--navy);color:#fff}.btn.gold{background:var(--gold);border-color:var(--gold);color:#fff}.btn.ghost{border-color:transparent}.action-overflow{position:relative}.action-overflow summary{list-style:none}.action-overflow summary::-webkit-details-marker{display:none}.action-menu{position:absolute;right:0;bottom:50px;width:260px;background:var(--white);border:1px solid var(--line);box-shadow:0 14px 36px rgba(8,20,36,.18);padding:8px}.action-menu .btn{display:block;width:100%;border:0;text-align:left}.capture,.editor,.preview{background:var(--white);padding:32px;margin:20px 0}.capture h2,.editor h2,.preview h2{font-family:Georgia,serif;font-size:26px;margin-top:0}.choice-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:24px}.choice{display:flex;gap:9px;align-items:flex-start;border:1px solid var(--line);padding:12px;background:#fff}.choice input{margin-top:5px}.edit-field{display:block;margin:0 0 18px}.edit-field>span{display:block;color:#5b6672;margin-bottom:7px}.edit-field textarea,.edit-field input,.edit-field select,select{width:100%;border:1px solid #cfc6b7;background:#fffdf8;padding:11px 12px;color:var(--ink)}.edit-field small{display:block;color:var(--muted);margin-top:4px}.form-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.client-sheet{background:white;max-width:690px;margin:0 auto;padding:44px;box-shadow:0 12px 35px rgba(10,20,30,.09)}.client-sheet .client-brand{color:var(--gold);letter-spacing:.15em;font-size:12px;font-weight:800}.client-sheet h2{font-family:Georgia,serif;font-size:32px;margin:8px 0}.client-score{font-size:13px;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:20px}.client-sheet h3{font-family:Georgia,serif;margin:27px 0 10px}.client-sheet p,.client-sheet li{font-size:15px}.client-risk{padding:15px 0;border-bottom:1px solid #eee}.contact-panel{background:var(--white);padding:30px}.contact-route{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}.contact-route span{color:var(--muted)}.empty{color:var(--muted);font-style:italic}.screen-note{text-align:center;color:var(--muted);padding:50px}.toast{max-width:720px;margin:40px auto;background:var(--white);padding:30px;border-top:3px solid var(--gold)}\n@media(max-width:760px){.topbar{height:48px;padding:0 16px}.topstate{font-size:10px}.paper{margin:0;box-shadow:none}.hero{padding:29px 20px 25px}.hero-layout{display:block}.hero h1{font-size:35px}.identity{font-size:16px}.hero-context{font-size:13px}.secondary-line{font-size:11px;margin-top:13px}.contact-card{margin-top:22px}.contact-card strong{font-size:18px}.hero-priority{grid-template-columns:1fr;margin-top:24px}.hero-signal{border-right:0;border-bottom:1px solid rgba(214,196,156,.25);padding:16px}.hero-signal:last-child{border-bottom:0}.executive-path{padding:24px 18px 6px;grid-template-columns:1fr;gap:9px}.path-card{min-height:0;padding:17px 18px}.memo{padding:24px 19px 96px}.section{display:block;padding:30px 0}.section-no{margin-bottom:8px}.section h2{font-size:24px}.pain-grid,.decision,.choice-grid{grid-template-columns:1fr}.opening{padding:23px 20px;font-size:18px}.statement{font-size:20px}.actionsbar{position:fixed;left:0;right:0;display:grid;grid-template-columns:1fr 1fr auto;padding:9px 10px;justify-content:stretch}.actionsbar>.btn{padding:11px 8px;font-size:13px}.action-overflow summary.btn{padding:11px 13px;font-size:13px}.action-menu{position:fixed;left:10px;right:10px;bottom:61px;width:auto}.capture,.editor,.preview,.contact-panel{padding:21px;margin-left:-1px;margin-right:-1px}.client-sheet{padding:26px 20px}.contact-route{grid-template-columns:1fr;gap:1px}h1{font-size:35px}}\n@media print{body{background:#fff}.topbar,.actionsbar,.capture{display:none}.paper{margin:0;box-shadow:none}.hero{-webkit-print-color-adjust:exact;print-color-adjust:exact}.memo{padding-bottom:0}}\n`;\n\nfunction shell(title, state, body, actions, lang) {\n  return '<!doctype html><html lang=\"' + (lang === 'ro' ? 'ro' : 'ru') + '\"><head><meta charset=\"utf-8\">'\n    + '<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"referrer\" content=\"no-referrer\">'\n    + '<title>' + esc(title) + '</title><style>' + SHELL_CSS + '</style></head><body>'\n    + '<header class=\"topbar\"><div class=\"brand\">FINMENTOR</div><div class=\"topstate\">' + esc(state) + '</div></header>'\n    + body + (actions || '') + '</body></html>';\n}\n\nfunction renderContact(contact, auth, company, state) {\n  const c = contact || {}; const routes = arr(c.reachable_channels);\n  const phone = routes.find((x) => (x.channel || x.key) === 'phone');\n  const email = routes.find((x) => (x.channel || x.key) === 'email');\n  const telegramReady = !!(c.telegram && c.telegram.reachable && c.telegram.verified && c.telegram.route);\n  const direct = '<div class=\"form-actions\">'\n    + (phone ? '<a class=\"btn\" href=\"tel:' + esc(String(phone.value).replace(/[^+\\d]/g, '')) + '\">Позвонить</a>' : '')\n    + (email ? '<a class=\"btn\" href=\"mailto:' + esc(email.value) + '\">Написать email</a>' : '') + '</div>';\n  const telegram = telegramReady && auth\n    ? '<div class=\"capture\"><div class=\"kind interpretation\">ПОДТВЕРЖДЁННЫЙ TELEGRAM</div><h2>Сообщение клиенту</h2><p>Сначала откроется предпросмотр. Отправка потребует отдельного подтверждения.</p><form method=\"post\">' + authInputs(auth, 'preview_outbound') + field('outbound_message', 'Здравствуйте! Это FINMENTOR. Предлагаю согласовать следующий шаг по вашему финансовому разбору.', 'Текст сообщения', { rows: 4, max: 1200 }) + '<button class=\"btn primary\" type=\"submit\">Предпросмотр сообщения</button></form></div>'\n    : '';\n  const manual = state === 'CLIENT_READY' && auth && !telegramReady\n    ? '<div class=\"capture\"><div class=\"kind fact\">РУЧНОЕ УВЕДОМЛЕНИЕ</div><h2>Клиент уведомлён вручную</h2><form method=\"post\">' + authInputs(auth, 'manual_notify') + '<label class=\"edit-field\"><span>Канал</span><select name=\"notification_channel\" required><option value=\"\">Выберите</option><option value=\"phone\">Телефон</option><option value=\"email\">Email</option><option value=\"telegram\">Telegram</option></select></label><button class=\"btn primary\" type=\"submit\">Зафиксировать</button></form></div>'\n    : '';\n  return '<div class=\"contact-panel\"><div class=\"kind fact\">КЛИЕНТ ГОВОРИТ</div><h2>Предпочтительно: ' + esc(c.preferred_label || 'Не указано') + '</h2>'\n    + (c.preferred_contact_channel === 'telegram' && !(c.telegram && c.telegram.reachable) ? '<p class=\"warn\">⚠️ Telegram-контакт не подключён</p>' : '')\n    + '<div class=\"kind fact\">ДОСТУПНО</div>'\n    + (routes.length ? routes.map((x) => '<div class=\"contact-route\"><span>' + esc(x.label) + '</span><strong>' + esc(x.value) + '</strong></div>').join('') : '<p class=\"empty\">Нет подтверждённого канала связи.</p>')\n    + direct + telegram + manual + '</div>';\n}\n\nfunction renderClientPreview(client, row) {\n  const c = client || {}; const fm = c.financial_maturity || {};\n  return '<div class=\"client-sheet\"><div class=\"client-brand\">FINMENTOR</div><h2>Финансовый разбор</h2>'\n    + '<div class=\"client-score\">' + (row.score === '' || row.score == null ? 'Без оценки' : esc(row.score) + ' / 100') + ' · ' + esc(zoneLabel(row.zone)) + '</div>'\n    + '<h3>Краткий вывод</h3>' + p(c.executive_summary)\n    + '<h3>Зрелость финансового управления</h3>' + p(fm.rationale)\n    + '<h3>Ключевые риски</h3>' + list(c.key_risks, (r) => '<div class=\"client-risk\"><strong>' + esc(r.title) + '</strong>' + p(r.potential_impact) + '</div>')\n    + '<h3>Приоритеты управления</h3><ol>' + arr(c.management_priorities).map((x) => '<li>' + esc(x) + '</li>').join('') + '</ol>'\n    + '<h3>План на 30 дней</h3>' + ['days_1_7','days_8_14','days_15_21','days_22_30'].map((w) => '<div class=\"client-risk\"><strong>' + esc(({days_1_7:'Дни 1–7',days_8_14:'Дни 8–14',days_15_21:'Дни 15–21',days_22_30:'Дни 22–30'})[w]) + '</strong><ul>' + arr((c.plan_30_days || {})[w]).map((x) => '<li>' + esc(x.action || x) + '</li>').join('') + '</ul></div>').join('')\n    + '<h3>Что сделать сейчас</h3><ul>' + arr(c.tomorrow_actions).map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>'\n    + '<h3>Рекомендация FINMENTOR</h3>' + p((c.recommended_next_step || {}).label, 'recommend') + p((c.recommended_next_step || {}).rationale)\n    + '</div>';\n}\n\nfunction renderEditor(client, auth) {\n  const c = client || {}; const fm = c.financial_maturity || {}; const plan = c.plan_30_days || {};\n  return '<div class=\"editor\"><div class=\"kind interpretation\">КЛИЕНТСКАЯ ВЕРСИЯ</div><h2>Редактирование результата</h2><p>Изменяются только клиентские формулировки. Оценка, зона и исходные ответы заблокированы.</p>'\n    + '<form method=\"post\">' + authInputs(auth, 'save_client_draft')\n    + field('executive_summary', c.executive_summary, 'Краткий вывод', { rows: 6 })\n    + field('maturity_rationale', fm.rationale, 'Объяснение зрелости', { rows: 4 })\n    + field('key_risks', asText(c.key_risks, (x) => [x.title, x.evidence, x.potential_impact].filter(present).join(' | ')), 'Ключевые риски', { rows: 7, hint: 'Один риск на строку: название | основание | последствие' })\n    + field('management_priorities', asText(c.management_priorities), 'Приоритеты управления', { rows: 4, hint: 'Один приоритет на строку' })\n    + field('plan_days_1_7', asText(plan.days_1_7, (x) => x.action || x), 'План · дни 1–7', { rows: 4 })\n    + field('plan_days_8_14', asText(plan.days_8_14, (x) => x.action || x), 'План · дни 8–14', { rows: 4 })\n    + field('plan_days_15_21', asText(plan.days_15_21, (x) => x.action || x), 'План · дни 15–21', { rows: 4 })\n    + field('plan_days_22_30', asText(plan.days_22_30, (x) => x.action || x), 'План · дни 22–30', { rows: 4 })\n    + field('tomorrow_actions', asText(c.tomorrow_actions), 'Действия сейчас', { rows: 4 })\n    + field('recommendation_label', (c.recommended_next_step || {}).label, 'Название рекомендации', { rows: 2 })\n    + field('recommendation_rationale', (c.recommended_next_step || {}).rationale, 'Обоснование рекомендации', { rows: 4 })\n    + '<div class=\"form-actions\"><button class=\"btn primary\" type=\"submit\">Сохранить</button><a class=\"btn\" href=\"?a=' + esc(auth.analysis_id) + '&amp;t=' + esc(auth.token) + '&amp;view=preview\">Предпросмотр клиента</a></div></form></div>';\n}\n\nfunction renderCapture(auth) {\n  const outcomes = [\n    ['PROBLEM_CONFIRMED','Проблема подтверждена'],['HYPOTHESIS_CHANGED','Гипотеза изменилась'],\n    ['MORE_DATA_NEEDED','Нужно больше данных'],['NO_TASK_NOW','Нет задачи сейчас'],['READY_TO_DISCUSS','Готов обсуждать работу']\n  ];\n  return '<div class=\"capture\" id=\"after-call\"><div class=\"kind interpretation\">ПОСЛЕ ЗВОНКА · ДО 60 СЕКУНД</div><h2>Зафиксировать разговор</h2><form method=\"post\">' + authInputs(auth, 'after_call')\n    + '<div class=\"choice-grid\">' + outcomes.map(([v,l]) => '<label class=\"choice\"><input type=\"radio\" name=\"conversation_outcome\" value=\"' + v + '\" required><span>' + esc(l) + '</span></label>').join('') + '</div>'\n    + field('confirmed', '', 'Что подтвердилось?', { rows: 3, max: 1200 })\n    + field('changed', '', 'Что оказалось иначе?', { rows: 3, max: 1200 })\n    + field('next_step_and_date', '', 'Следующий шаг + дата', { rows: 2, max: 800, hint: 'Например: получить ageing дебиторки — 15.09.2026' })\n    + '<button class=\"btn primary\" type=\"submit\">Сохранить разговор</button></form></div>';\n}\n\nfunction renderOutboundConfirm(preview, auth) {\n  const p0 = preview || {};\n  return '<article class=\"paper\"><main class=\"memo\"><div class=\"preview\"><div class=\"kind verify\">ПРОВЕРКА ПЕРЕД ОТПРАВКОЙ</div><h2>Отправить ' + esc(p0.recipient || 'клиенту') + '?</h2><div class=\"opening\">' + esc(p0.message) + '</div><form method=\"post\">' + authInputs(auth, 'send_outbound') + '<textarea name=\"outbound_message\" hidden>' + esc(p0.message) + '</textarea><div class=\"form-actions\"><button class=\"btn gold\" type=\"submit\">Подтвердить</button><a class=\"btn\" href=\"?a=' + encodeURIComponent((auth || {}).analysis_id || '') + '&amp;t=' + encodeURIComponent((auth || {}).token || '') + '&amp;view=contact\">Отмена</a></div></form></div></main></article>';\n}\n\nfunction renderBriefBody(brief, row, auth) {\n  const b = brief || {}; const h = b.header || {}; const c = b.contact || {};\n  const factNames = Object.fromEntries(arr(b.client_facts).map((f) => [f.id, f.label]));\n  const evidence = (ids) => arr(ids).map((id) => factNames[id]).filter(Boolean).join(' · ');\n  const reachableSummary = arr(c.reachable_channels).map((x) => x.label).join(', ') || 'Нет подтверждённых каналов';\n  const pain = arr(b.client_facts).find((f) => f.id === 'main_problem') || arr(b.client_facts)[0] || {};\n  const insight = arr(b.diagnoses)[0] || {};\n  const verify = arr(b.unknowns)[0] || {};\n  const solution = b.solution_hypothesis || {};\n  const next = b.next_action || {};\n  const score = h.diagnostic_score == null ? 'Без оценки' : esc(h.diagnostic_score) + ' / 100 · ' + esc(zoneLabel(h.financial_zone));\n  const hero = '<article class=\"paper\"><header class=\"hero\"><div class=\"hero-layout\"><div><div class=\"eyebrow\">Lead Intelligence · конфиденциально</div><h1>' + esc(h.company || 'Компания не указана') + '</h1>'\n    + '<p class=\"identity\">' + esc([h.contact_name, h.role].filter(present).join(' · ') || 'Контакт не указан') + '</p>'\n    + '<p class=\"hero-context\">' + esc([h.business,h.scale].filter(present).join(' · ') || 'Контекст бизнеса не указан') + '</p>'\n    + '<p class=\"secondary-line\">' + score + ' &nbsp;·&nbsp; ' + esc(sourceLabel(h.source)) + ' &nbsp;·&nbsp; ' + esc(h.data_quality || 'Требует проверки') + '</p></div>'\n    + '<div class=\"contact-card\"><span class=\"micro\">Контакт сейчас</span><strong>' + esc(c.preferred_label || 'Не указано') + '</strong>'\n    + (c.preferred_contact_channel === 'telegram' && !(c.telegram && c.telegram.reachable) ? '<p class=\"warn\">Telegram-контакт не подключён</p>' : '')\n    + '<p>Доступно: ' + esc(reachableSummary) + '</p></div></div>'\n    + '<div class=\"hero-priority\"><div class=\"hero-signal\"><span class=\"micro\">Главная боль</span><strong>' + esc(pain.value || 'Нужно уточнить') + '</strong></div>'\n    + '<div class=\"hero-signal\"><span class=\"micro\">Вывод FINMENTOR</span><strong>' + esc(insight.conclusion || 'Формируется') + '</strong></div>'\n    + '<div class=\"hero-signal\"><span class=\"micro\">Следующее действие</span><strong>' + esc(next.action || h.next_action || 'Нужно определить') + '</strong></div></div></header>'\n    + '<section class=\"executive-path\" aria-label=\"Логика решения\">'\n    + '<article class=\"path-card\" data-stage=\"pain\"><div class=\"path-step\">01 · Боль</div><h2>Что происходит</h2><p>' + esc(pain.value || 'Нужно уточнить') + '</p></article>'\n    + '<article class=\"path-card\" data-stage=\"insight\"><div class=\"path-step\">02 · FINMENTOR</div><h2>Что это значит</h2><p>' + esc(insight.conclusion || 'Формируется') + '</p></article>'\n    + '<article class=\"path-card\" data-stage=\"verify\"><div class=\"path-step\">03 · Проверить</div><h2>Чего не хватает</h2><p>' + esc(verify.item || 'Нужно определить') + '</p></article>'\n    + '<article class=\"path-card\" data-stage=\"conversation\"><div class=\"path-step\">04 · Разговор</div><h2>Как открыть</h2><p>' + esc(b.conversation_opening || 'Нужно подготовить') + '</p></article>'\n    + '<article class=\"path-card\" data-stage=\"solution\"><div class=\"path-step\">05 · Решение</div><h2>Рабочая гипотеза</h2><p>' + esc(solution.format || solution.rationale || 'Сначала уточнение') + '</p></article>'\n    + '<article class=\"path-card\" data-stage=\"next-action\"><div class=\"path-step\">06 · Действие</div><h2>Что сделать сейчас</h2><p>' + esc(next.action || h.next_action || 'Нужно определить') + '</p></article></section>';\n\n  const notes = arr(b.owner_confirmed_facts).map((x) => '<div class=\"owner-note\"><div class=\"kind\">' + provenanceLabel('OWNER_CONFIRMED_FACT') + '</div>' + p(x.text || x.value) + '</div>').join('')\n    + arr(b.owner_notes).map((x) => '<div class=\"owner-note\"><div class=\"kind\">' + provenanceLabel('OWNER_NOTE') + '</div>' + p(x.text || x.value) + '</div>').join('');\n\n  const body = '<main class=\"memo\">' + (notes ? '<section>' + notes + '</section>' : '')\n    + '<section class=\"section\"><div class=\"section-no\">01</div><div><div class=\"kind fact\">КЛИЕНТ ГОВОРИТ</div><h2>Что говорит клиент</h2>'\n    + list(b.client_facts, (f) => '<div class=\"fact-row\" data-kind=\"CLIENT_FACT\"><h3>' + esc(f.label) + '</h3>' + p(f.value) + '</div>') + '</div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">02</div><div><div class=\"kind interpretation\">FINMENTOR ВИДИТ</div><h2>Диагноз FINMENTOR</h2>'\n    + list(b.diagnoses, (d) => '<div class=\"diagnosis\" data-kind=\"FINMENTOR_INTERPRETATION\"><h3>Профессиональный вывод</h3>' + p(d.conclusion) + (d.hypothesis ? p('Гипотеза: ' + d.hypothesis, 'hypothesis') : '') + (d.economic_implication ? p(d.economic_implication, 'why') : '') + (evidence(d.evidence_fact_ids) ? p('Основание: ' + evidence(d.evidence_fact_ids), 'evidence') : '') + '</div>') + '</div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">03</div><div><div class=\"kind interpretation\">FINMENTOR ВИДИТ</div><h2>Карта боли</h2><div class=\"pain-grid\">'\n    + arr(b.pain_map).map((x) => '<article class=\"pain\"><div class=\"attention\">' + esc(x.attention) + '</div><h3>' + esc(x.area) + '</h3>' + p(x.observation) + p('Почему важно: ' + x.consequence, 'why') + '</article>').join('') + '</div></div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">04</div><div><div class=\"kind verify\">НУЖНО ПРОВЕРИТЬ</div><h2>Что нужно проверить</h2>'\n    + list(b.unknowns, (u, i) => '<div class=\"unknown\" data-kind=\"NEEDS_VERIFICATION\"><div class=\"mark\">?</div><div><strong>' + esc(u.item) + '</strong>' + p(u.why) + '</div></div>') + '</div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">05</div><div><div class=\"kind interpretation\">РЕШЕНИЕ ДЛЯ ВСТРЕЧИ</div><h2>Цель первой встречи</h2><p class=\"statement\">' + esc(b.first_meeting_objective) + '</p></div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">06</div><div><div class=\"kind interpretation\">ПЕРВЫЕ 30 СЕКУНД</div><h2>Как начать разговор</h2><div class=\"opening\">“' + esc(b.conversation_opening) + '”</div></div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">07</div><div><div class=\"kind interpretation\">ЛОГИКА ДИАГНОСТИКИ</div><h2>Вопросы первой встречи</h2>'\n    + arr(b.discovery_questions).map((q, i) => '<div class=\"question\"><div class=\"qno\">' + String(i + 1).padStart(2, '0') + '</div><div><strong>' + esc(q.question) + '</strong><p><b>Зачем:</b> ' + esc(q.why) + '</p></div></div>').join('') + '</div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">08</div><div><div class=\"kind interpretation\">РАБОЧАЯ ГИПОТЕЗА</div><h2>Рабочая гипотеза решения</h2><div class=\"solution\">'\n    + '<div class=\"solution-row\"><div class=\"micro\">Вероятный формат</div>' + p(b.solution_hypothesis && b.solution_hypothesis.format) + '</div>'\n    + '<div class=\"solution-row\"><div class=\"micro\">Почему</div>' + p(b.solution_hypothesis && b.solution_hypothesis.rationale) + '</div>'\n    + '<div class=\"solution-row\"><div class=\"micro\">Что должно подтвердиться</div><ul class=\"conditions\">' + arr(b.solution_hypothesis && b.solution_hypothesis.confirmation_conditions).map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul></div>'\n    + ((b.solution_hypothesis || {}).if_confirmed ? '<div class=\"solution-row\"><div class=\"micro\">Если подтвердится</div>' + p(b.solution_hypothesis.if_confirmed) + '</div>' : '')\n    + ((b.solution_hypothesis || {}).do_not_offer_yet ? '<div class=\"solution-row\"><div class=\"micro\">Пока не предлагать</div>' + p(b.solution_hypothesis.do_not_offer_yet) + '</div>' : '') + '</div></div></section>'\n    + '<section class=\"section\"><div class=\"section-no\">09</div><div><div class=\"kind interpretation\">РЕШЕНИЕ ВЛАДЕЛЬЦА</div><h2>Следующее действие</h2><div class=\"decision\">'\n    + '<div><span class=\"micro\">Действие</span>' + p((b.next_action || {}).action) + '<span class=\"micro\">Цель</span>' + p((b.next_action || {}).purpose) + '</div>'\n    + '<div><span class=\"micro\">Успешный результат</span>' + p((b.next_action || {}).success_condition) + ((b.next_action || {}).due_date ? '<span class=\"micro\">Срок</span>' + p(b.next_action.due_date) : '') + '</div></div></div></section>'\n    + '<details class=\"details\"><summary>Исходные ответы</summary><div class=\"details-body\">' + arr(b.client_facts).map((f) => '<p><strong>' + esc(f.label) + ':</strong> ' + esc(f.value) + '</p>').join('') + '</div></details>'\n    + '<details class=\"details\"><summary>История</summary><div class=\"details-body\">' + (arr(b.history).length ? arr(b.history).map((x) => '<p>' + esc([x.at,x.label].filter(present).join(' — ')) + '</p>').join('') : '<p>История действий пока пуста.</p>') + '</div></details>'\n    + '<details class=\"details\"><summary>Контакты</summary><div class=\"details-body\">' + renderContact(c, auth, h.company, row.review_status) + '</div></details>'\n    + renderCapture(auth) + '</main></article>';\n  return hero + body;\n}\n\nfunction renderOwnerBriefPage(opts) {\n  const o = opts || {}; const brief = o.brief || {}; const row = o.row || {}; const auth = o.auth || {};\n  const state = statusLabel(row.review_status); const mode = o.mode || 'brief';\n  let content;\n  const clientEligible = brief.client_result_eligible === true;\n  if (mode === 'edit' && !clientEligible) content = '<article class=\"paper\"><main class=\"memo\"><div class=\"toast\"><div class=\"kind verify\">ТОЛЬКО ДЛЯ ВЛАДЕЛЬЦА</div><h1>Клиентский результат не предусмотрен</h1><p>Исходный путь не содержал явного запроса или обещания клиентского разбора.</p></div></main></article>';\n  else if (mode === 'edit') content = '<article class=\"paper\"><main class=\"memo\">' + renderEditor(o.client_draft, auth) + '</main></article>';\n  else if (mode === 'preview' && !clientEligible) content = '<article class=\"paper\"><main class=\"memo\"><div class=\"toast\"><div class=\"kind verify\">ТОЛЬКО ДЛЯ ВЛАДЕЛЬЦА</div><h1>Предпросмотр недоступен</h1><p>Клиент выбрал самооценку; публикация результата заблокирована.</p></div></main></article>';\n  else if (mode === 'preview') content = '<article class=\"paper\"><main class=\"memo\"><div class=\"preview\"><div class=\"kind fact\">ТОЧНО ТАК УВИДИТ КЛИЕНТ</div><h2>Предпросмотр клиента</h2>' + renderClientPreview(o.client_draft, row) + (clientEligible && !['CLIENT_READY','CLIENT_NOTIFIED','CLIENT_VIEWED'].includes(String(row.review_status || '')) ? '<form method=\"post\">' + authInputs(auth, 'approve') + '<div class=\"form-actions\"><button class=\"btn gold\" type=\"submit\">Утвердить и сделать доступным</button></div></form>' : '') + '</div></main></article>';\n  else if (mode === 'contact') content = '<article class=\"paper\"><main class=\"memo\">' + renderContact(brief.contact, auth, (brief.header || {}).company, row.review_status) + '</main></article>';\n  else content = renderBriefBody(brief, row, auth);\n  const qs = '?a=' + encodeURIComponent(auth.analysis_id || '') + '&amp;t=' + encodeURIComponent(auth.token || '');\n  const overflow = clientEligible ? '<details class=\"action-overflow\"><summary class=\"btn\">Ещё</summary><div class=\"action-menu\"><a class=\"btn\" href=\"' + qs + '&amp;view=edit\">Редактировать результат</a><a class=\"btn\" href=\"' + qs + '&amp;view=preview\">Предпросмотр клиента</a></div></details>' : '';\n  const actions = '<nav class=\"actionsbar\"><a class=\"btn primary\" data-primary-action href=\"' + qs + '\">Разбор</a><a class=\"btn\" data-primary-action href=\"' + qs + '&amp;view=contact\">Связаться</a>' + overflow + '</nav>';\n  return shell('FINMENTOR · ' + ((brief.header || {}).company || 'Разбор клиента'), state, content, actions, row.locale);\n}\n\nfunction renderMessagePage(title, message, state) {\n  return shell('FINMENTOR · ' + title, state || '', '<div class=\"toast\"><h1>' + esc(title) + '</h1>' + p(message) + '</div>', '', 'ru');\n}\nreturn { renderOwnerBriefPage, renderMessagePage, renderOutboundConfirm };\n})();\n\nconst transport = $input.first().json || {};\nconst verdict = $('Review POST Verdict').first().json || {};\nconst delivered = transport.ok === true || String(transport.ok).toLowerCase() === 'true';\nreturn [{ json: {\n  delivered,\n  http_status: delivered ? 200 : 502,\n  activity_row: delivered ? verdict.activity_row : null,\n  html: delivered\n    ? LI_RENDER.renderMessagePage('Сообщение отправлено', 'Доставка через FINMENTOR Client Transport подтверждена.', 'DELIVERED')\n    : LI_RENDER.renderMessagePage('Сообщение не отправлено', 'Транспорт не подтвердил доставку. Запись об успешном контакте не создана.', 'DELIVERY_FAILED')\n} }];\n" } },
  output: [{ delivered: true, http_status: 200, activity_row: {}, html: '' }]
});

const ifOutboundDelivered = ifElse({
  version: 2.2,
  config: { name: 'IF Outbound Delivered', parameters: { conditions: { options: { caseSensitive: true, leftValue: '', typeValidation: 'strict' },
    conditions: [{ leftValue: expr('{{ $json.delivered }}'), operator: { type: 'boolean', operation: 'true', singleValue: true } }], combinator: 'and' } } }
});

const outboundActivityRow = node({
  type: 'n8n-nodes-base.set', version: 3.4,
  config: { name: 'Outbound Activity Row', parameters: { mode: 'raw', jsonOutput: expr('{{ JSON.stringify($json.activity_row) }}'), options: {} } },
  output: [{ activity_id: '', ts: '', lead_id: '', actor: '', channel: 'telegram', action: 'outbound_contact', detail: '' }]
});

const appendOutboundActivity = node({
  type: 'n8n-nodes-base.googleSheets', version: 4.7,
  config: { name: 'Append Outbound Activity', retryOnFail: true, onError: 'continueRegularOutput',
    parameters: { resource: 'sheet', operation: 'append', documentId: {"__rl":true,"value":"1CyZJPhCAvhnJjQOOoAF4COqU2wAFNqKu2Gw7ngjpN5A","mode":"list","cachedResultName":"FINMENTOR_LEADS_CRM_PREMIUM_FINAL"}, sheetName: {"__rl":true,"value":623316892,"mode":"list","cachedResultName":"Activities"},
      columns: { mappingMode: 'autoMapInputData', value: {}, matchingColumns: [], schema: [] }, options: { cellFormat: 'RAW' } }, credentials: { googleSheetsOAuth2Api: { id: 'PzVCuEPa9YF3YSaD', name: 'Google Sheets OAuth2 API' } } },
  output: [{ activity_id: '', lead_id: '' }]
});

const respondOutbound = node({
  type: 'n8n-nodes-base.respondToWebhook', version: 1.5,
  config: { name: 'Respond Outbound Result', parameters: { respondWith: 'text', responseBody: expr("{{ $('Complete Outbound Contact').item.json.html }}"),
    options: { responseCode: expr("{{ $('Complete Outbound Contact').item.json.http_status }}"), responseHeaders: { entries: [{ name: 'Content-Type', value: 'text/html; charset=utf-8' }, { name: 'Cache-Control', value: 'no-store' }, { name: 'Referrer-Policy', value: 'no-referrer' }, { name: 'X-Robots-Tag', value: 'noindex, nofollow' }] } } } },
  output: [{}]
});

export default workflow('finmentor-xray-analysis', 'FINMENTOR X-Ray Analysis')
  .add(sweepTrigger)
  .to(readSettings)
  .to(settingsToObject)
  .to(readPipeline)
  .to(readAnalysis)
  .to(readActivities)
  .to(readStatusLog)
  .to(selectPending)
  .to(readLeadRaw)
  .to(buildInput)
  .to(ifInputReady
    .onTrue(aiAnalysis
      .onError(failedRowBuild.to(failedRow.to(saveFailed.to(ownerFailureNotice))))
      .to(validateRows
        .to(analysisRow
          .to(saveAnalysis
            .to(pipelineRow
              .to(updatePipeline
                .to(ifAnalysisValid
                  .onTrue(ifNotifyOwner.onTrue(ownerAlert))
                  .onFalse(validationFailureNotice))))))))
    .onFalse(sourceAuditNotice))
  .add(reviewGetWebhook)
  .to(readForReviewGet)
  .to(reviewSurface)
  .to(respondReviewSurface)
  .add(reviewPostWebhook)
  .to(readForReviewPost)
  .to(reviewVerdict)
  .to(ifPersist
    .onTrue(promoteRow.to(promoteAnalysis.to(pipelineStatusRow.to(updatePipelineStatus.to(reviewActivityRow.to(appendReviewActivity.to(ifPublishClient
      .onTrue(buildClientResult.to(publishClientResult.to(buildReadyNotification.to(ifAutoNotify
        .onTrue(readyTransportRequest.to(sendReadyNotification.to(completeReadyNotification.to(ifReadyDelivered
          .onTrue(notifiedAnalysisRow.to(updateNotifiedAnalysis.to(notifiedPipelineRow.to(updateNotifiedPipeline.to(notifiedActivityRow.to(appendNotifiedActivity.to(respondReadyNotification)))))))
          .onFalse(respondReadyNotification)))))
        .onFalse(respondPromoted)))))
      .onFalse(respondPromoted))))))))
    .onFalse(ifSendCustomer
      .onTrue(outboundTransportRequest.to(sendCustomerMessage.to(completeOutbound.to(ifOutboundDelivered
        .onTrue(outboundActivityRow.to(appendOutboundActivity.to(respondOutbound)))
        .onFalse(respondOutbound)))))
      .onFalse(respondDenied)));
